import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_SIGNING_KEY = os.environ.get('HMAC_KEY', 'dev-key-not-for-prod')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL,
        department TEXT DEFAULT 'general'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token format: username:timestamp:signature
        parts = token.split(':')
        if len(parts) != 3:
            return jsonify({'error': 'malformed token'}), 401
        username, ts, sig = parts
        expected = hmac.new(SECRET_SIGNING_KEY.encode(), f'{username}:{ts}'.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user = username
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_session
def search_users():
    """Search users by department and optional name filter.
    Used by the internal directory UI for autocomplete."""
    department = request.args.get('dept', 'general')
    name_filter = request.args.get('q', '')
    role_filter = request.args.get('role', '')

    # Build query with department filter
    base_query = f"SELECT username, email, department, role FROM users WHERE department = '{department}'"

    if name_filter:
        # Additional filter - note: department already constrains results
        base_query += f" AND username LIKE '%{name_filter}%'"

    if role_filter:
        base_query += f" AND role = '{role_filter}'"

    db = get_db()
    try:
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search for compliance
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', g.current_user, f'dept={department},q={name_filter}')
        )
        db.commit()

        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
@verify_session
def get_profile(user_id):
    db = get_db()
    cursor = db.execute("SELECT username, email, department, role FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
